/**
 * Session Package Types — Sawaa Dashboard
 *
 * Response shapes are DERIVED from the committed OpenAPI snapshot
 * (`lib/types/api.generated.ts`, regenerated by `pnpm openapi:sync`), so a
 * backend response change becomes a type error here instead of drifting
 * silently. Money is integer halalas end-to-end; the two Prisma Decimal
 * columns (`discountValue`, `unitPrice`) stay decimal strings on the wire and
 * are coerced with `Number()` where the UI needs arithmetic.
 *
 * Request payloads, query params and the client-side price preview stay local
 * and are marked as such.
 */

import type { components } from "@/lib/types/api.generated"
import type { PaginatedQuery } from "./common"
import type {
  GlobalDiscount,
  PackageGroupInput,
  PackageModelVersion,
} from "@sawaa/shared/types"

type Schemas = components["schemas"]

/* ─── Entities (derived from OpenAPI) ─── */

/** Wire vocabulary of the persisted item discount. */
export type PackageDiscountType = NonNullable<Schemas["PackageItemRecordDto"]["discountType"]>

/** Wire vocabulary re-exported for the package editors. */
export type PackageModelVersionValue = Schemas["PackageListRowDto"]["modelVersion"]
export type PackageSequenceMode = Schemas["PackageGroupReadDto"]["sequenceMode"]
export type PackageDeliveryType = Schemas["PackageGroupSessionReadDto"]["deliveryType"]

/** One persisted package item with its eligibility constraints (GET list/detail). */
export type SessionPackageItem = Schemas["PackageItemRecordDto"]
/** Read-side constraint row, targets nested as rows. */
export type PackageConstraintResponse = Schemas["PackageItemConstraintRecordDto"]

/**
 * GET /dashboard/organization/packages row: the persisted package decorated
 * with its editor projection (`groups`, `globalDiscount`) and the flattened
 * canonical price (`ComputePackagePriceService`).
 */
export type SessionPackage = Schemas["PackageListRowDto"]

/**
 * GET /dashboard/organization/packages/:packageId: the same decorated package
 * with the price as a nested breakdown instead of flattened row columns.
 */
export type SessionPackageDetail = Schemas["PackageDetailResponseDto"]

/**
 * The fields both list rows and the detail share. Package editors receive
 * either response (the detail query, or a row handed in by the list page), so
 * they type against this and never touch the price columns.
 */
export type PackageEditorEntity = Omit<
  SessionPackage,
  "subtotal" | "discountAmount" | "finalPrice" | "fullValue" | "freeValue" | "vatRate"
>

/** Package-wide discount union as documented (`PackageGlobalDiscount`). */
export type PackageGlobalDiscount = SessionPackage["globalDiscount"]

/** POST / PATCH response: the raw persisted row (legacy items, or grouped groups). */
export type PackageWriteResponse =
  | Schemas["PackageLegacyWriteResponseDto"]
  | Schemas["PackageGroupedWriteResponseDto"]

/* ─── Constraint/editing vocabulary ─── */

/**
 * A package item's eligibility is expressed per dimension:
 *   SERVICE → service ids · PRACTITIONER → employee ids ·
 *   DURATION → durationOption id · DELIVERY_TYPE → 'IN_PERSON' | 'ONLINE'.
 */
export type PackageConstraintDimension = Schemas["PackageConstraintInputDto"]["dimension"]

/** ANY = no targets (matches all) · INCLUDE/EXCLUDE = ≥1 target. */
export type PackageConstraintMode = Schemas["PackageConstraintInputDto"]["mode"]

/** Write-side constraint (what we send on create/update). */
export type PackageConstraintInput = Schemas["PackageConstraintInputDto"]

/** Form-only choice; the API continues to use constraints, not this enum. */
export type PackageSelectionMode = "FIXED" | "FLEXIBLE"

/* ─── Item payloads (write side, local to the dashboard) ─── */

/**
 * Item body sent to create/update. Local rather than derived: the request DTO
 * accepts `discountType: null` ("omit/null for no discount") and the committed
 * snapshot documents the enum without `nullable`, so the generated request type
 * would reject a valid body.
 */
export interface CreatePackageItemPayload {
  /** Legacy single-service UUID. Omit for flexible items (use constraints). */
  serviceId?: string
  /** Legacy single-practitioner UUID. Omit for flexible items (use constraints). */
  employeeId?: string
  /** Legacy single ServiceDurationOption UUID. Omit for flexible items (use constraints). */
  durationOptionId?: string
  /** Multi-dimensional eligibility. Preferred over the legacy triple — always sent. */
  constraints?: PackageConstraintInput[]
  /** Fixed prepaid unit price (integer halalas). Required for flexible items. */
  unitPrice?: number
  /** Optional display label. */
  label?: string
  paidQuantity: number
  freeQuantity?: number
  /** Per-item discount. PERCENTAGE: 0-100. FIXED: integer halalas. null/omit = none. */
  discountType?: PackageDiscountType | null
  discountValue?: number
  sortOrder?: number
}

export type UpdatePackageItemPayload = CreatePackageItemPayload

/* ─── Package payloads (write side, local to the dashboard) ─── */

/** Legacy (non-grouped) create body. */
export interface LegacySessionPackagePayload {
  nameAr: string
  nameEn?: string
  descriptionAr?: string
  descriptionEn?: string
  imageUrl?: string | null
  iconName?: string | null
  iconBgColor?: string | null
  /** DEPRECATED — discount now lives per-item. Backend ignores these. */
  discountType?: PackageDiscountType
  discountValue?: number
  isActive?: boolean
  isPublic?: boolean
  sortOrder?: number
  /** Null creates a general package; omission is accepted for old callers. */
  ownerEmployeeId?: string | null
  items?: CreatePackageItemPayload[]
}

/**
 * Create body. The legacy fields and the grouped V2 fields share one object
 * because the two editors post to the same endpoint and the handler branches on
 * `modelVersion`; the grouped editor leaves the legacy-only fields out.
 */
export interface CreateSessionPackagePayload extends LegacySessionPackagePayload {
  modelVersion?: PackageModelVersion
  groups?: PackageGroupInput[]
  globalDiscount?: GlobalDiscount
}

export type UpdateSessionPackagePayload = Partial<CreateSessionPackagePayload> & {
  items?: CreatePackageItemPayload[]
}

/* ─── Queries ─── */

export interface PackageListQuery extends PaginatedQuery {
  search?: string
  isActive?: boolean
  isPublic?: boolean
}

/* ─── Price breakdown (client-side preview only — list/get send a price) ─── */

/** Per-line price detail (integer halalas) — mirrors the backend `lines[]`. */
export interface PackageLineBreakdown {
  fullValue: number // (paid + free) × unit
  freeValue: number // free × unit
  payable: number // paid × unit
  discountAmount: number // item discount on payable
  net: number // payable − discount
}

export interface PackagePriceBreakdown {
  subtotal: number // Σ payable (paid × unit)
  discountAmount: number // Σ per-item discount
  finalPrice: number // subtotal − discountAmount
  fullValue: number // Σ fullValue (incl. free sessions)
  freeValue: number // Σ freeValue
  totalSavings: number // freeValue + discountAmount
  lines: PackageLineBreakdown[]
}
